{%- import 'afintrix_theme/templates/print/afintrix_print.html' as afx -%}
<div class="afx-print">
	{{ afx.head(_('Payment Receipt'), doc.name, [
		(_('Date'), frappe.utils.formatdate(doc.posting_date)),
		(_('Mode'), doc.mode_of_payment),
		(_('Reference'), doc.reference_no),
	]) }}

	{{ afx.parties([
		(_('Received from') if doc.payment_type == 'Receive' else _('Paid to'), doc.party_name, ''),
		(_('Company'), doc.company, ''),
	]) }}

	{%- if doc.references %}
	{{ afx.table_open([
		(_('Against'), '46%', 'left'),
		(_('Outstanding'), '27%', 'right'),
		(_('Allocated'), '27%', 'right'),
	]) }}
	{%- for row in doc.references %}
	<tr>
		<td>{{ loop.index }}</td>
		{{ afx.item_cell(row.reference_name, row.reference_doctype) }}
		<td class="text-right">{{ frappe.utils.fmt_money(row.outstanding_amount, currency=doc.paid_from_account_currency) }}</td>
		<td class="text-right">{{ frappe.utils.fmt_money(row.allocated_amount, currency=doc.paid_from_account_currency) }}</td>
	</tr>
	{%- endfor %}
	{{ afx.table_close() }}
	{%- endif %}

	{{ afx.summary([
		(_('Amount'), frappe.utils.fmt_money(doc.paid_amount, currency=doc.paid_from_account_currency), True),
	]) }}

	{{ afx.terms(_('Remarks'), doc.remarks) }}
	{{ afx.signatures(_('Authorised signatory'), _('Received by')) }}
</div>
